	public static void GetAttribute(global::ZoneID zoneId, global::UnityEngine.Vector2Int grid, out int code, out int stop, bool debugdraw = false) {
            if (zoneId != global::ZoneID.UNKNOWN)
            {
                GetAttribute(GetMapAttributeMattrix(zoneId), grid, out code, out stop, debugdraw);
                return;
            }
            code = 0;
            stop = 0;
        }
	public static global::XLSXContent.MapAttributeTable.SheetData GetAttributeTable(int code) {
            return Instance.gameSettings.mapAttributeTable.Data[code];
        }
	public static void GetAttribute(global::XLSXContent.AttributeMatrix attributes, global::UnityEngine.Vector2Int grid, out int code, out int stop, bool debugdraw = false) {
            code = 0;
            stop = 0;
            if (grid.x >= 0 && grid.y >= 0 && attributes != null)
            {
                global::XLSXContent.AttributeBlock block = attributes[grid.x / 32, grid.y / 32];
                if (block != null && block.Attributes != null)
                {
                    int attribute = block[grid.x % 32, grid.y % 32];
                    if (attribute < 1000)
                    {
                        stop = attribute;
                    }
                    else
                    {
                        code = attribute / 1000;
                        stop = attribute % 1000;
                    }
                }
            }
        }
	public static global::XLSXContent.MapAttributeExTable.SheetData GetAttributeEx(global::UnityEngine.Vector2Int grid, float height, bool debugdraw = false) {
            int raw = GetAttributeExCodeRaw(grid);
            int code = HeightAttribute(raw, height);
            for (int i = 0; i < Instance.gameSettings.mapAttributeExTable.Data.Length; i++)
            {
                if (Instance.gameSettings.mapAttributeExTable.Data[i].Code == code)
                {
                    if (debugdraw)
                    {
                        // the shipped build still formats this text; its output call is stripped
                        string log = string.Format("{0} :: {1} ::", Instance.gameSettings.mapAttributeExTable.Data[i].Code, Instance.gameSettings.mapAttributeExTable.Data[i].EffectWalkSunnyA)
                            + string.Format(" {0} :: Threshold:{1}", Instance.gameSettings.mapAttributeExTable.Data[i].EffectWalkSunnyB, raw / 1000000);
                    }
                    return Instance.gameSettings.mapAttributeExTable.Data[i];
                }
            }
            return null;
        }
	public static int GetAttributeExCodeRaw(global::UnityEngine.Vector2Int grid) {
            if (global::PlayerWork.zoneID != global::ZoneID.UNKNOWN)
            {
                global::XLSXContent.AttributeMatrix attributes = GetMapAttributeExMattrix();
                if (attributes != null)
                {
                    global::XLSXContent.AttributeBlock block = attributes[grid.x / 32, grid.y / 32];
                    if (block != null && block.Attributes != null)
                        return block[global::System.Math.Max(grid.x % 32, 0), global::System.Math.Max(grid.y % 32, 0)];
                }
            }
            return 0;
        }
	public static bool IsHighAttribute(int attriRaw, float height) {
            return attriRaw / 1000000 <= (int)(height + 100.5f);
        }
	public static int HeightAttribute(int attri, float height) {
            if (attri / 1000000 <= (int)(height + 100.5f))
                attri /= 1000;
            return attri % 1000;
        }
	public static global::ZoneID GetGridZoneID(global::UnityEngine.Vector2Int pos) {
            global::XLSXContent.MapInfo.SheetZoneData zoneData = mapInfo[(int)global::PlayerWork.zoneID];
            if (zoneData.ZoneGrid != null)
            {
                uint index = (uint)(pos.y / 32 * zoneData.ZoneGrid.Width + pos.x / 32);
                if (index < zoneData.ZoneGrid.Length)
                    return zoneData.ZoneGrid[(int)index];
            }
            return global::ZoneID.UNKNOWN;
        }
