            string[] files = new string[0];
            for (int i = 0; i < files.Length; i++)
                global::SmartPoint.AssetAssistant.AssetBundleMemory.LoadFromFile(global::SmartPoint.AssetAssistant.UnityExtensions.StringExtensions.CombinePath(global::SmartPoint.AssetAssistant.AssetManager.cachePath, files[i]));
        }
	public static bool CPU_BOOST_ON() {
            if (global::PlayerWork.IsCpuBoostMode == 0)
                return false;
            if (global::PlayerWork.IsCpuBoostMode > 2)
                global::UnityEngine.Application.backgroundLoadingPriority = global::UnityEngine.ThreadPriority.High;
            if (global::PlayerWork.IsCpuBoostMode > 1)
            {
                if (fieldCamera != null)
                    fieldCamera.CameraComponentEnable(false);
            }
#if SWITCH
            // TO CHECK: Switch-only API, mode value 1 from the binary
            global::UnityEngine.Switch.Performance.SetCpuBoostMode((global::UnityEngine.Switch.Performance.CpuBoostMode)1);
#endif
            return true;
        }
	public static bool CPU_BOOST_OFF() {
            if (global::PlayerWork.IsCpuBoostMode == 0)
                return false;
            global::UnityEngine.Application.backgroundLoadingPriority = global::UnityEngine.ThreadPriority.BelowNormal;
            if (global::PlayerWork.IsCpuBoostMode > 1)
            {
                if (fieldCamera != null)
                    fieldCamera.CameraComponentEnable(true);
            }
#if SWITCH
            // TO CHECK: Switch-only API, mode value 0 from the binary
            global::UnityEngine.Switch.Performance.SetCpuBoostMode((global::UnityEngine.Switch.Performance.CpuBoostMode)0);
#endif
            return true;
        }
